# t54-s3: sequential vs hierarchical 两种 Crew 执行模式
class MiniCrew:
    def __init__(self, tasks: list, process: str = "sequential", max_iter: int = 8):
        self.tasks = {t["name"]: t for t in tasks}
        self.order = [t["name"] for t in tasks]  # 声明顺序
        self.process = process
        self.max_iter = max_iter

    def kickoff(self) -> dict:
        if self.process == "sequential":
            return self._run_sequential()
        return self._run_hierarchical()

    def _run_sequential(self) -> dict:
        results, path = {}, []
        for name in self.order:
            path.append(name)
            results[name] = self.tasks[name]["work"]()
        return {"results": results, "path": path, "llm_calls": len(self.order)}

    def _run_hierarchical(self) -> dict:
        results, path = {}, []
        done = set()
        llm_calls = 0
        for _ in range(self.max_iter):
            remaining = [n for n in self.order if n not in done]
            if not remaining:
                break
            # manager 决策(模拟): 选第一个未完成的
            chosen = remaining[0]
            llm_calls += 1  # manager 分派 = 1次调用
            path.append(f"manager→{chosen}")
            output = self.tasks[chosen]["work"]()
            # manager 验收(模拟): 输出长度>10字通过
            llm_calls += 1  # 验收又1次调用
            if len(output) > 10:
                results[chosen] = output
                done.add(chosen)
                path.append(f"{chosen}✓")
            else:
                path.append(f"{chosen}✗打回")
        return {"results": results, "path": path, "llm_calls": llm_calls}


TASKS = [
    {"name": "research", "desc": "调研注意力机制", "work": lambda: "资料: QKV点积加权求和"},
    {"name": "write", "desc": "写科普文", "work": lambda: "科普文: 注意力就像读书时划重点"},
    {"name": "review", "desc": "审校", "work": lambda: "审校通过: 准确且易懂"},
]

if __name__ == "__main__":
    for mode in ["sequential", "hierarchical"]:
        r = MiniCrew(TASKS, process=mode).kickoff()
        print(f"=== {mode} ===")
        print(f"  路径: {' → '.join(r['path'])}")
        print(f"  LLM调用数: {r['llm_calls']}")
        print()
    print("结论: hierarchical 多了 manager 的分派+验收调用, 成本约2倍, 但获得动态编排能力")
